    Bug 1943520 - Add option to clearAll() to always clear the web browser. r=standard8,vineet

    We currently set `#keepStartPageOpen = false` almost every time before
    we call `clearWebPage()`. The only case were this safty mechanism is
    actually needed is when `clearAll()` is called, which by default should
    not clear the web browser if the start page is still shown. There is no
    real need for the default behavior of `clearWebPage()` to have that
    exception for the start page.

    Once the web browser *has* been cleared, it will always be cleared
    (except someting is setting `#keepStartPageOpen` back to true).

    This patch moves setting `#keepStartPageOpen = false` into
    `clearWebPage()`. The exception is directly handled in `clearAll()` by
    checking the value of `#keepStartPageOpen` and skipping to clear the web
    browser if needed.

    For the case where `clearAll()` should indeed also clear the web
    browser, this patch introduces an optional option.

    This patch sightly improves code readability and simplifies clearing all
    browsers including the web browser, if that is needed. With the current
    code, one hast to call `displayWebPage()` with no params and then call
    `clearAll()`.

    Differential Revision: https://phabricator.services.mozilla.com/D237881

diff --git a/mail/base/content/widgets/message-pane.mjs b/mail/base/content/widgets/message-pane.mjs
index d7858f497b7..2ce2d8bd492 100644
--- a/mail/base/content/widgets/message-pane.mjs
+++ b/mail/base/content/widgets/message-pane.mjs
@@ -263,24 +263,33 @@ class MessagePane extends HTMLElement {
   }

   /**
-   * Ensure all message pane browsers are blank.
+   * Ensure all message pane browsers are blank. Default behavior is to not clear
+   * the web browser, if the start page is still being displayed.
+   *
+   * @param {object} [options]
+   * @param {boolean} [options.alwaysClearWebBrowser] - Clear the web browser,
+   *    even if it is still displaying the start page.
    */
-  clearAll() {
+  clearAll(options) {
     this.#hideCurrentFindBar();
-    this.clearWebPage();
+    if (options?.alwaysClearWebBrowser) {
+      this.#keepStartPageOpen = false;
+    }
+    if (!this.#keepStartPageOpen) {
+      this.clearWebPage();
+    }
     this.#clearMessage();
     this.#clearMessages();
   }

   /**
-   * Ensure the web page browser is blank, unless the start page is shown.
+   * Ensure the web page browser is blank.
    */
   clearWebPage() {
-    if (!this.#keepStartPageOpen) {
-      this.webBrowser.hidden = true;
-      this.webBrowser.docShellIsActive = false;
-      MailE10SUtils.loadAboutBlank(this.webBrowser);
-    }
+    this.#keepStartPageOpen = false;
+    this.webBrowser.hidden = true;
+    this.webBrowser.docShellIsActive = false;
+    MailE10SUtils.loadAboutBlank(this.webBrowser);
   }

   /**
@@ -296,7 +305,6 @@ class MessagePane extends HTMLElement {
     }

     if (!url || url == "about:blank") {
-      this.#keepStartPageOpen = false;
       this.clearWebPage();
       return;
     }
@@ -345,7 +353,6 @@ class MessagePane extends HTMLElement {
       return;
     }

-    this.#keepStartPageOpen = false;
     this.clearWebPage();
     this.#clearMessages();

@@ -391,7 +398,6 @@ class MessagePane extends HTMLElement {
       return;
     }

-    this.#keepStartPageOpen = false;
     this.clearWebPage();
     this.#clearMessage();
